// One public Shell invocation. A new Shell inherits its caller's Job;
// Shell alone decides whether to start or reuse an existing instance.
export async function obtainShell(settings,{call,timeoutMs=30000}={}) {
  const start=await call({module:'desktop',request:{action:'obtain_start',
    executable:settings.executable,yamlPath:settings.yamlPath,
    localAppData:settings.localAppData,dshHome:settings.dshHome}});
  if(start.error)throw Object.assign(Error(start.error),{code:start.code,path:start.path});
  let timer;
  try{
    const result=await Promise.race([
      call({module:'desktop',request:{action:'obtain_read',owner:start.owner}}),
      new Promise((_resolve,reject)=>{timer=setTimeout(()=>reject(Error('Shell opening timed out; the operation may still be in progress')),timeoutMs);}),
    ]);
    if(result.cancelled===true)throw Object.assign(Error('Shell opening cancelled'),{cancelled:true,result:{phase:'cancelled'}});
    if(result.ready!==true)throw Error(result.error??'Shell did not acknowledge readiness');
    if(typeof result.origin!=='string'||!/^http:\/\/127\.0\.0\.1:\d+$/.test(result.origin)
      ||typeof result.nonce!=='string'||!result.nonce)throw Error('Shell returned incomplete connection data');
    return {origin:result.origin,nonce:result.nonce};
  }finally{clearTimeout(timer);}
}
